/*
We need the median of medians of all subarrays.

Key fact:
For a candidate value X, define b[i] = +1 if a[i] >= X, else -1.
For a subarray, its "lower median" is >= X iff sum(b[l..r]) > 0.
So the number of subarrays whose median >= X equals the number of pairs
(i < j) with prefix[j] > prefix[i], where prefix[0]=0, prefix[k]=sum_{1..k} b.

Then we can binary search the maximum X such that count >= needed,
where needed = ceil(total_subarrays / 2).
*/

typedef struct {
    int n;
    ll *bit;
} BIT;

static void bit_init(BIT *ft, int n) {
    ft->n = n;
    ft->bit = (ll *)calloc((size_t)(n + 1), sizeof(ll));
}

static void bit_free(BIT *ft) {
    free(ft->bit);
}

static void bit_add(BIT *ft, int idx, ll val) {
    while (idx <= ft->n) {
        ft->bit[idx] += val;
        idx += idx & -idx;
    }
}

static ll bit_sum(BIT *ft, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += ft->bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

static ll count_ge_median(const ll *a, int n, ll x) {
    int m = 2 * n + 5;
    int offset = n + 2;

    BIT ft;
    bit_init(&ft, m);

    int pref = 0;
    ll cnt = 0;

    bit_add(&ft, offset, 1); // prefix 0

    for (int i = 0; i < n; i++) {
        if (a[i] >= x) pref++;
        else pref--;

        int idx = pref + offset;

        // count previous prefixes strictly less than current prefix
        cnt += bit_sum(&ft, idx - 1);

        bit_add(&ft, idx, 1);
    }

    bit_free(&ft);
    return cnt;
}

