public class Main {
    // Fenwick Tree / BIT for prefix sums
    static class Fenwick {
        int n;
        long[] bit;
        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }
        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += val;
        }
        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }
    }

    static int N;
    static int[] a;

    // Count subarrays whose median is >= x
    static long countGE(int x) {
        // Transform: >= x => +1, < x => -1
        // For a subarray, median >= x iff transformed sum > 0
        // Let prefix sums be p[0..N]. Need count of pairs i < j with p[j] > p[i].
        int[] pref = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            pref[i] = pref[i - 1] + (a[i - 1] >= x ? 1 : -1);
        }

        // Coordinate compression of prefix sums
        int[] vals = pref.clone();
        Arrays.sort(vals);
        int m = 1;
        for (int i = 1; i <= N; i++) {
            if (vals[i] != vals[m - 1]) vals[m++] = vals[i];
        }

        Fenwick fw = new Fenwick(m + 2);
        long count = 0;

        for (int i = 0; i <= N; i++) {
            int pos = lowerBound(vals, m, pref[i]) + 1; // 1-indexed
            // count previous prefix sums strictly less than current
            count += fw.sum(pos - 1);
            fw.add(pos, 1);
        }
        return count;
    }

    static int lowerBound(int[] arr, int len, int target) {
        int l = 0, r = len;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        a = new int[N];
        int minV = Integer.MAX_VALUE, maxV = Integer.MIN_VALUE;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextInt();
            minV = Math.min(minV, a[i]);
            maxV = Math.max(maxV, a[i]);
        }

        long total = (long) N * (N + 1) / 2;
        long need = (total + 1) / 2; // lower median position in sorted m

        int lo = minV, hi = maxV;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (countGE(mid) >= need) lo = mid;
            else hi = mid - 1;
        }

        System.out.println(lo);
    }

    // Fast input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

